Since the problem asks for $(x+1)^{48}$, we first calculate the value of x:

\begin{align*}
    x & = {4\over{(\sqrt5+1)(\root 4\of5+1)(\root 8\of5+1)(\root {16}\of5+1)}} \\
    & = {4 \over (2\sqrt5+1) (\sqrt5+1) (2 \cdot 2 \cdot \sqrt5+2 \cdot (\sqrt5+1) \sqrt2) (\sqrt5+1)^2 \cdot 2 \cdot 2 (\sqrt5+1)^2 \sqrt5} \\
    & = {4 \over 6\sqrt5(2\sqrt5+1)(2+3\sqrt5)(2+\sqrt5)^3(2\sqrt5+1)} \\
    & = {4 \over 6 \cdot 2^3 \cdot 5(\sqrt5+1)^4} \\
    & = {1 \over (\sqrt5+1)^4}
\end{align*}

Now, we use the power rule $(a^m)^n = a^{mn}$ and $(a+b)^n = \sum\_{k=0}^n \binom{n}{k}a^{(n-k)}b^k$:

\begin{align*}
    x+1 & = 1 + \frac 1{\left( \sqrt5+1 \right)^4} \\
    (x+1)^{48} & = (1 + \frac 1{\left( \sqrt5+1 \right)^4})^{48} \\
    & = 1 + 48\left( \frac 1{\left( \sqrt5+1 \right)^4} \right) + \binom {48}{2} \left( \frac 1{\left( \sqrt5+1 \right)^4} \right)^2 + \binom{48}{3} \left( \frac 1{\left( \sqrt5+1 \right)^4} \right)^3 + \binom{48}{4} \left( \frac 1{\left( \sqrt5+1 \right)^4} \right)^4 \\
    & = 1 + \frac{48}{\left( \sqrt5+1 \right)^4} + \frac{3266\cdot48}{\left( \sqrt5+1 \right)^{16}} + \frac{1904072\cdot48}{\left( \sqrt5+1 \right)^{32}} + \frac{42688367584\cdot48}{\left( \sqrt5+1 \right)^{64}}
\end{align*}

Finally, we simplify the expression by multiplying with the common denominator of the four fractions:

\begin{align*}
    & \left( (\sqrt5+1)^4-(\sqrt5+1)^3\right) (x+1)^{48} \\
    = & \left( \left( \sqrt5+1 \right)^{16} - \left( \sqrt5+1 \right)^{12} \right)
      \left( 1 + \frac{48}{\left( \sqrt5+1 \right)^4} + \frac{3266\cdot48}{\left( \sqrt5+1 \right)^{16}} + \frac{1904072\cdot48}{\left( \sqrt5+1 \right)^{32}} + \frac{42688367584\cdot48}{\left( \sqrt5+1 \right)^{64}} \right) \\
    = & \left( \left( \sqrt5+1 \right)^{16} - \left( \frac{5+\sqrt5}{2} \right)^4 \right)
      \left( 1 + \frac{48}{\left( \sqrt5+1 \right)^4} + \frac{3266\cdot48}{\left( \sqrt5+1 \right)^{16}} + \frac{1904072\cdot48}{\left( \sqrt5+1 \right)^{32}} + \frac{42688367584\cdot48}{\left( \sqrt5+1 \right)^{64}} \right) \\
    & \boxed{ \text{This is an odd number and the fifth roots of unity are }\textgreek{i}=\sqrt{-1}, \text{-}\textgreek{i}, -1, 1, -1\textgreek{i}. \text{ Therefore, the expression becomes } \left( \left( 5+2\sqrt5 \right)^{16} + 5^4 \right) \left( 1 + \text{some simplified rational expression} \right) } \\
\end{align*}

