&= \left ( \frac{20}{24} + \frac{3}{24} \right ) \frac{\text{side } CDEF \sqrt{3}}{2} \\
&= \frac{5}{8}\frac{\text{side } CDEF \sqrt{3}}{2} + \frac{3}{8}\frac{\text{side } CDEF \sqrt{3}}{2} \\
&= \frac{\text{side } CDEF \sqrt{3}}{4} \left ( \frac{5}{8} + \frac{3}{8} \right )
\end{align*}

Remember to put the units at the end:
\begin{align*}
\text{edge sum} &= 2\text{side } PE + 2\cdot \text{side } PH + \text{side } PA \\
&= 4\cdot \left ( \frac{5\text{side } CDEF \sqrt{3}}{12} \right ) + 2\cdot \left ( \frac{5\text{side } CDEF}{12} \right ) + \frac{\text{side } CDEF \sqrt{3}}{4} \left ( \frac{5}{8} + \frac{3}{8} \right ) \\
&= \frac{25\text{side } CDEF \sqrt{3}}{12} + \frac{25\text{side } CDEF}{24} + \frac{25\text{side } CDEF \sqrt{3}}{48} \\
