\begin{document}

Apply the formula for the sum of a geometric series:

\begin{align*}
\sum_{k=1}^{1728} \frac{1}{1 + \omega^{k} + \omega^{2k} + \omega^{3k}}
&= \sum_{k=1}^{1728} \frac{1}{\omega^{(k-1)(2 \cdot 1 + 2\cdot 2 + 3\cdot 3)}} \\
&= \sum_{k=1}^{1728} \frac{1}{\omega^{(k-1)(1729)}} \\
\text{Sum from }k=1\text{ to }1728\text{ of the geometric sequence }\frac{1}{\omega^{(k-1)(1729)}} \text{ with common ratio }\omega^{-1729} \\
&= \frac{1 - \omega^{-1729\cdot1728}}{1 - \omega^{-1729}} \\
\text{Multiply the sum by }\omega^{1729}\text{ to simplify the expression} \\
&= \frac{\omega^{1729} - 1}{\omega^{1729} - \omega^{-1729}} \\
\text{Express the denominator in terms of }\omega \text{ and square it} \\
&= \frac{\omega^{1729} - 1}{(-\omega^{1729} + \omega^{1729})} \\
&= \frac{\omega^{1729} - 1}{\omega^{3458}} \\
\text{Since }e^{i \pi} &= -1, \omega^{3458} &= (e^{2\pi i / 1729})^{3458} &= e^{3458\pi i / 1729} &= e^{10\pi i} &=& -1 \\
\text{Therefore, } \omega^{3458} &= -1 \\
\boxed{\frac{\omega^{1729}-1}{-1}}
\end{align*}

\end{document}
