\begin{document}

\text{The product of the first 20 positive integers is:}

\begin{equation*}
\prod\limits_{i=1}^{20} i = \boxed{ \prod_{i=1}^{20} i = 2432902008176640000 }%
\end{equation*}

Find the smallest positive integer $n$ such that $\gcd(n, \prod_{i=1}^{20} i) = 1$:

\begin{enumerate}
\item Attempt values based on the definition of being relatively prime:
\begin{equation*}
\gcd(n, \prod_{i=1}^{20} i) = 1
\end{equation*}

\item Start with $n = 2$ since 1 is not applicable for the problem and is smaller than the product of any number of integers.
\begin{equation*}
\gcd(2, \prod_{i=1}^{20} i) = 2
\end{equation*}

\item Test $n = 3$
\begin{equation*}
\gcd(3, \prod_{i=1}^{20} i) = 3
\end{equation*}

\item Test $n = 4$
