    ylabel={$\mathbbm{1}(x) \cdot f(x) g(x)$},
    domain=-4:4,
    smooth, samples=100,
    grid=major]
\addplot {5*x^4};
\end{axis}
\end{tikzpicture}
\end{center}
From the graph, we can visually see symmetry about the y-axis, confirming that $f(x)g(x)$ is even.

