&= \mod \left(-\frac{4\pi}{3},2\pi\right) \\
&= \frac{4\pi}{3}
\end{align*}
In degrees:
\begin{align*}
\theta &= \frac{4\pi}{3} \cdot \frac{180}{\pi} \\
